    ["<Assistant_Title1>First Glimpse of Mystery</>\n<Assistant_Title2>Achievement Category: </>Growth - Development\n<Assistant_Title2>Unlock Condition: </>Reach Acting Level 10"] = "<Assistant_Title1>Первый взгляд на секрет</>\n<Assistant_Title2>Категория достижения: </>Воспитание-рост\n<Assistant_Title2>Условия разблокировки: </>Повысьте свою роль до уровня 10",
